  actual_count bigint;
  actual_hash text;
BEGIN
  IF (SELECT id FROM public.anki_deck_releases WHERE status='published' ORDER BY published_at DESC LIMIT 1) IS DISTINCT FROM '7764b632-5622-4f1b-959d-1874908fc46d'::uuid THEN RAISE EXCEPTION 'Current deck changed'; END IF;
  IF EXISTS (SELECT 1 FROM public.anki_deck_release_cards rc JOIN public.anki_deck_releases r ON r.id=rc.deck_release_id WHERE rc.canonical_card_id=ANY(card_ids) AND r.status IN ('published','superseded','retired')) THEN RAISE EXCEPTION 'Candidate belongs to released history'; END IF;
  SELECT count(*), md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY t.id),'')) INTO actual_count,actual_hash FROM public.canonical_cards t WHERE t.id=ANY(card_ids) AND t.is_active;
  IF actual_count<>1425 OR actual_hash<>'e442ba17737d717614a89021fae3ae31' THEN RAISE EXCEPTION 'Before-state changed: canonical_cards'; END IF;
  UPDATE public.canonical_cards t SET is_active=false WHERE t.id=ANY(card_ids) AND t.is_active;
  GET DIAGNOSTICS actual_count = ROW_COUNT;
  IF actual_count<>1425 THEN RAISE EXCEPTION 'Unexpected update count: canonical_cards'; END IF;
  SELECT count(*), md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY t.id),'')) INTO actual_count,actual_hash FROM public.anki_cards t WHERE t.id IN (SELECT anki_card_id FROM public.canonical_cards WHERE id=ANY(card_ids)) AND t.is_active;
  IF actual_count<>1425 OR actual_hash<>'365cd7ab9850d5bb59a9863c1d072857' THEN RAISE EXCEPTION 'Before-state changed: anki_cards'; END IF;
  UPDATE public.anki_cards t SET is_active=false WHERE t.id IN (SELECT anki_card_id FROM public.canonical_cards WHERE id=ANY(card_ids)) AND t.is_active;
  GET DIAGNOSTICS actual_count = ROW_COUNT;
  IF actual_count<>1425 THEN RAISE EXCEPTION 'Unexpected update count: anki_cards'; END IF;
  SELECT count(*), md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY t.id),'')) INTO actual_count,actual_hash FROM public.card_canonical_entity_links t WHERE t.canonical_card_id=ANY(card_ids) AND t.is_active;
  IF actual_count<>29 OR actual_hash<>'df9a9cb9695815868703d0f536cbd9b4' THEN RAISE EXCEPTION 'Before-state changed: card_canonical_entity_links'; END IF;
  UPDATE public.card_canonical_entity_links t SET is_active=false WHERE t.canonical_card_id=ANY(card_ids) AND t.is_active;
  GET DIAGNOSTICS actual_count = ROW_COUNT;
  IF actual_count<>29 THEN RAISE EXCEPTION 'Unexpected update count: card_canonical_entity_links'; END IF;
  SELECT count(*), md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY t.id),'')) INTO actual_count,actual_hash FROM public.card_knowledge_links t WHERE t.canonical_card_id=ANY(card_ids) AND t.is_active;
  IF actual_count<>70 OR actual_hash<>'988fab19cbe6951af90f745e03b64d9f' THEN RAISE EXCEPTION 'Before-state changed: card_knowledge_links'; END IF;
  UPDATE public.card_knowledge_links t SET is_active=false WHERE t.canonical_card_id=ANY(card_ids) AND t.is_active;
  GET DIAGNOSTICS actual_count = ROW_COUNT;
  IF actual_count<>70 THEN RAISE EXCEPTION 'Unexpected update count: card_knowledge_links'; END IF;
  SELECT count(*), md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY t.id),'')) INTO actual_count,actual_hash FROM public.anki_kg_mapping_candidates t WHERE t.canonical_card_id=ANY(card_ids) AND t.is_active;
  IF actual_count<>860 OR actual_hash<>'57ee380953aaf43f21ece08b8a9cc07a' THEN RAISE EXCEPTION 'Before-state changed: anki_kg_mapping_candidates'; END IF;
  UPDATE public.anki_kg_mapping_candidates t SET is_active=false WHERE t.canonical_card_id=ANY(card_ids) AND t.is_active;
  GET DIAGNOSTICS actual_count = ROW_COUNT;
  IF actual_count<>860 THEN RAISE EXCEPTION 'Unexpected update count: anki_kg_mapping_candidates'; END IF;
  IF (SELECT count(*) FROM public.canonical_cards WHERE is_active)<>3670 THEN RAISE EXCEPTION 'Active card count mismatch'; END IF;
  IF EXISTS(SELECT 1 FROM public.anki_deck_release_cards r JOIN public.canonical_cards c ON c.id=r.canonical_card_id JOIN public.anki_cards a ON a.id=c.anki_card_id WHERE r.deck_release_id='7764b632-5622-4f1b-959d-1874908fc46d' AND r.inclusion_status='included' AND (NOT c.is_active OR NOT a.is_active)) THEN RAISE EXCEPTION 'Current card deactivated'; END IF;
END $cleanup$;
COMMIT;
SELECT count(*) FILTER (WHERE is_active) AS active_cards,count(*) FILTER (WHERE NOT is_active) AS inactive_cards FROM public.canonical_cards;
